/* ---------- contracts ---------- */
function startContract(initial = false) {
  missionDone = false; extractVisible = false; extractBeacon.visible = false;
  let picks;
  if (initial) picks = [0, 1, 2];
  else {
    const pool = [...Array(packageSpots.length).keys()].filter(i => i !== 0).sort(() => rnd() - .5);
    picks = pool.slice(0, 3);
  }
  packages.forEach((p, i) => {
    const spot = packageSpots[picks[i]];
    p.x = spot.x; p.z = spot.z; p.got = false; p.beacon.position.set(p.x, 0, p.z); p.beacon.visible = true;
  });
  const ex = extractSpots[(job + (initial ? 0 : 1)) % extractSpots.length];
  extraction.x = ex.x; extraction.z = ex.z; extractBeacon.position.set(ex.x, 0, ex.z);
  el.missionCopy.textContent = initial
    ? 'Three encrypted drops went dark across the district. Secure them, then reach the extraction beacon.'
    : 'A fresh contract just landed. New package coordinates are live — the district has already noticed.';
  updateHUD(true);
}
function completeContract() {
  if (missionDone) return;
  missionDone = true;
  const reward = 1200 + job * 300, xp = 110 + job * 20;
  addCash(reward); gainXP(xp); player.heat = Math.min(10, player.heat + 1);
  showToast('JOB COMPLETE · +$' + reward.toLocaleString() + ' · +' + xp + ' XP', 'good'); sfx.win();
  burst(player.x, 1.2, player.z, '#66f0c2', 28, 7);
  setTimeout(() => {
    if (!playing) return;
    job++; startContract(false); showToast('NEW CONTRACT · JOB ' + String(job).padStart(2, '0'), 'good');
  }, 5200);
}

/* ---------- doors / interiors / vehicles ---------- */
function nearestEnterable() {
  let best = null, bd = 4.2;
  for (const e of enterables) { const d = dist2(player.x, player.z, e.x, e.z); if (d < bd) { bd = d; best = e; } }
  return best;
}
function nearestCar() {
  let best = null, bd = 4.5;
  for (const c of cars) { const d = dist2(player.x, player.z, c.x, c.z); if (d < bd) { bd = d; best = c; } }
  return best;
}
function enterInterior(e) {
  currentInterior = e; savedExit = { x: e.x, z: e.z + 2.2, yaw: cameraYaw };
  mode = 'interior'; world.visible = false; interior.visible = true;
  player.x = 0; player.z = 3.2; player.angle = Math.PI; playerModel.group.position.set(0, .12, 3.2); playerModel.group.rotation.y = Math.PI;
  player.vehicle = null; playerModel.group.visible = true; medUsed = false;
  cameraYaw = 0; cameraPitch = .12; camera.position.set(0, 2.2, 8.2);
  const col = '#' + e.color.toString(16).padStart(6, '0');
  const mat = new THREE.SpriteMaterial({ map: textTexture(e.name + ' · ARMORY', col, '#081013'), transparent: true, toneMapped: false, depthWrite: false });
  interiorSign.material.dispose(); interiorSign.material = mat; interiorSign.scale.set(8.4, 2.1, 1);
  p1.color.set(e.color); interiorExitGlow.material.color.set(e.color);
  showToast('INTERIOR · ' + e.name + ' · WALK TO THE ARMORY', 'good'); sfx.drive();
}
function exitInterior() {
  mode = 'street'; interior.visible = false; world.visible = true;
  player.x = savedExit.x; player.z = savedExit.z; player.angle = savedExit.yaw + Math.PI;
  playerModel.group.position.set(player.x, .12, player.z); cameraYaw = savedExit.yaw;
  showToast('BACK ON THE STREET'); sfx.drive();
}
function enterVehicle(car) {
  mode = 'vehicle'; player.vehicle = car; car.speed = 0; playerModel.group.visible = false;
  cameraYaw = car.angle + Math.PI; cameraPitch = .2; player.angle = car.angle;
  showToast(car.name + ' ACQUIRED · W/S DRIVE · A/D STEER · E EXIT'); sfx.drive();
}
function exitVehicle() {
  const c = player.vehicle; if (!c) return;
  const side = c.angle + Math.PI / 2;
  let px = c.x + Math.sin(side) * 2.7, pz = c.z + Math.cos(side) * 2.7;
  if (blockedAt(px, pz, .55)) { px = c.x - Math.sin(side) * 2.7; pz = c.z - Math.cos(side) * 2.7; }
  if (blockedAt(px, pz, .55)) { px = c.x - Math.sin(c.angle) * 3.4; pz = c.z - Math.cos(c.angle) * 3.4; }
  player.x = px; player.z = pz; playerModel.group.position.set(px, .12, pz);
  player.vehicle = null; c.speed = 0; mode = 'street'; playerModel.group.visible = true; player.angle = c.angle;
  showToast('ON FOOT · STAY SHARP');
}
function interact() {
  if (!playing || shopOpen) return;
  if (mode === 'interior') {
    if (dist2(player.x, player.z, interiorAnchors.exit.x, interiorAnchors.exit.z) < 2.5) { exitInterior(); return; }
    if (dist2(player.x, player.z, interiorAnchors.terminal.x, interiorAnchors.terminal.z) < 2.7) { setShop(true); return; }
    if (dist2(player.x, player.z, interiorAnchors.med.x, interiorAnchors.med.z) < 2.5) {
      if (medUsed) { showToast('MED STATION ALREADY USED THIS VISIT', 'bad'); sfx.deny(); return; }
      medUsed = true; player.hp = player.maxHp; showToast('MED STATION · VITALS RESTORED', 'good'); sfx.pickup(); updateHUD(true); return;
    }
    return;
  }
  if (mode === 'vehicle') { exitVehicle(); return; }
  const car = nearestCar();
  if (car) { enterVehicle(car); return; }
  const door = nearestEnterable();
  if (door) { enterInterior(door); return; }
  if (packages.every(p => p.got) && !missionDone && dist2(player.x, player.z, extraction.x, extraction.z) < 5.5) { completeContract(); return; }
}

/* ---------- shooting ---------- */
function currentWeapon() { return WEAPONS[player.weapon]; }
function wallDistance(ox, oz, dx, dz, max = 70) {
  for (let d = 1; d < max; d += 1) if (blockedAt(ox + dx * d, oz + dz * d, .06)) return d;
  return max;
}
function shoot() {
  const w = currentWeapon();
  if (player.fireCd > 0 || mode !== 'street' || shopOpen) return;
  player.fireCd = w.rate;
  let baseAngle;
  let autoTarget = null;
  if ('ontouchstart' in window || touch.fire) {
    let bd = 45; for (const e of enemies) if (!e.dead) { const d = dist2(player.x, player.z, e.x, e.z); if (d < bd) { bd = d; autoTarget = e; } }
  }
  if (autoTarget) baseAngle = Math.atan2(autoTarget.x - player.x, autoTarget.z - player.z);
  else baseAngle = Math.atan2(-Math.sin(cameraYaw), -Math.cos(cameraYaw));
  player.angle = baseAngle; playerModel.group.rotation.y = baseAngle;
  const muzzle = new THREE.Vector3(); playerModel.muzzle.getWorldPosition(muzzle);
  for (let i = 0; i < w.pellets; i++) {
    const spread = (Math.random() - .5) * w.spread * 2;
    const a = baseAngle + spread, dx = Math.sin(a), dz = Math.cos(a);
    const wallD = Math.min(w.range, wallDistance(player.x, player.z, dx, dz, w.range));
    let best = null, bestT = wallD + .3;
    for (const e of enemies) {
      if (e.dead) continue;
      const ex = e.x - player.x, ez = e.z - player.z;
      const t = ex * dx + ez * dz;
      if (t < .8 || t > bestT) continue;
      const perp = Math.abs(ex * dz - ez * dx);
      if (perp < .72 && t < bestT) { bestT = t; best = e; }
    }
    let end;
    if (best) {
      end = new THREE.Vector3(best.x, 1.18, best.z);
      let dmg = w.damage + (w.pellets > 1 ? player.damageBonus * .45 : player.damageBonus);
      damageEnemy(best, dmg, a);
    } else {
      end = new THREE.Vector3(player.x + dx * wallD, 1.2 + (Math.random() - .5) * .35, player.z + dz * wallD);
      if (wallD < w.range) burst(end.x, end.y, end.z, '#ffd9a0', 2, 2);
    }
    tracer(muzzle, end, w.color, w.pellets > 1 ? .8 : 1.4);
  }
  burst(muzzle.x, muzzle.y, muzzle.z, w.color, w.pellets > 1 ? 7 : 3, 3);
  cameraShake = Math.min(.22, cameraShake + (w.pellets > 1 ? .12 : .045));
  if (w.pellets > 1) sfx.shotgun(); else sfx.shot();
  for (const e of enemies) if (!e.dead && dist2(e.x, e.z, player.x, player.z) < 46) e.alert = 4;
}
function melee() {
  if (mode !== 'street' || player.fireCd > .2) return;
  player.fireCd = .45; let hit = false;
  for (const e of enemies) {
    if (e.dead) continue; const d = dist2(e.x, e.z, player.x, player.z);
    if (d < 2.5) { const a = Math.atan2(e.x - player.x, e.z - player.z); const diff = Math.atan2(Math.sin(a - player.angle), Math.cos(a - player.angle)); if (Math.abs(diff) < 1.2) { damageEnemy(e, 46, a); hit = true; } }
  }
  if (hit) showToast('CLEAN HIT'); else burst(player.x + Math.sin(player.angle), 1.2, player.z + Math.cos(player.angle), '#b8c8c2', 3, 2);
}

/* ---------- player + vehicle updates ---------- */
let walkPhase = 0;
function updatePlayer(dt) {
  let ax = (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0);
  let ay = (keys.KeyS || keys.ArrowDown ? 1 : 0) - (keys.KeyW || keys.ArrowUp ? 1 : 0);
  if (touch.move.active) { ax = touch.move.x; ay = touch.move.y; }
  const mag = Math.hypot(ax, ay); if (mag > 1) { ax /= mag; ay /= mag; }
  const sprint = keys.ShiftLeft || keys.ShiftRight || touch.boost;
  let speed = (sprint ? 7.8 : 5.1) * (1 + player.speedBonus);
  if (player.dash > 0) speed = 17 * (1 + player.speedBonus);
  const fx = -Math.sin(cameraYaw), fz = -Math.cos(cameraYaw);
  const rx = Math.cos(cameraYaw), rz = -Math.sin(cameraYaw);
  const dx = rx * ax + fx * (-ay), dz = rz * ax + fz * (-ay);
  const len = Math.hypot(dx, dz);
  if (len > .05) {
    walkPhase += dt * (speed > 8 ? 13 : 9);
    const nx = player.x + dx / len * speed * dt, nz = player.z + dz / len * speed * dt;
    if (!blockedAt(nx, player.z, .46)) player.x = nx;
    if (!blockedAt(player.x, nz, .46)) player.z = nz;
    if (player.dash <= 0) {
      const target = Math.atan2(dx, dz);
      if (!mouse.down && !touch.fire) player.angle = lerpAngle(player.angle, target, 1 - Math.exp(-14 * dt));
    }
  }
  player.x = clamp(player.x, -292, 292); player.z = clamp(player.z, -292, 292);
  if (mouse.down || touch.fire) player.angle = Math.atan2(-Math.sin(cameraYaw), -Math.cos(cameraYaw));
  else if ('ontouchstart' in window && touch.fire) {
    let bd = 45, tgt = null; for (const e of enemies) if (!e.dead) { const d = dist2(player.x, player.z, e.x, e.z); if (d < bd) { bd = d; tgt = e; } }
    if (tgt) player.angle = lerpAngle(player.angle, Math.atan2(tgt.x - player.x, tgt.z - player.z), 1 - Math.exp(-12 * dt));
  }
  playerModel.group.position.set(player.x, .12 + (len > .05 ? Math.abs(Math.sin(walkPhase * 2)) * .035 : 0), player.z);
  playerModel.group.rotation.y = player.angle;
  const swing = len > .05 ? Math.sin(walkPhase) * .72 : 0;
  playerModel.legs[0].rotation.x = swing; playerModel.legs[1].rotation.x = -swing;
  playerModel.arms[0].rotation.x = -.55 - swing * .35; playerModel.arms[1].rotation.x = -.55 + swing * .35;
  if (player.fireCd > 0) playerModel.arms[1].rotation.x = -.85;
  playerModel.group.rotation.z = player.dash > 0 ? .1 : 0;
}
function updateVehicle(dt) {
  const c = player.vehicle; if (!c) { mode = 'street'; return; }
  const throttle = (keys.KeyW || keys.ArrowUp ? 1 : 0) - (keys.KeyS || keys.ArrowDown ? 1 : 0);
  const steer = (keys.KeyD || keys.ArrowRight ? 1 : 0) - (keys.KeyA || keys.ArrowLeft ? 1 : 0);
  const accel = (throttle > 0 ? 16 : throttle < 0 ? 9 : 0) * (1 + upgrades.speed * .2);
  c.speed += accel * dt;
  if (throttle === 0) c.speed *= Math.pow(.55, dt);
  if (keys.Space) c.speed *= Math.pow(.08, dt);
  c.speed = clamp(c.speed, -8.5, 27);
